<main class="main-content"><header class="topbar"><div><span class="eyebrow">LIBRARY OPERATIONS</span><h1>Members</h1></div></header><section class="content-card"><?php flash_html();?><div class="section-heading"><div><h2>Members register</h2><p>DL Group Two members and other registered library users.</p></div><a class="btn" href="create.php">＋ Add member</a></div><form class="search-form"><input name="q" value="<?=e($q)?>" placeholder="Search name, member number, email or phone"><button class="btn">Search</button><a class="btn btn-secondary" href="index.php">Reset</a></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Member no.</th><th>Student ID</th><th>Full name</th><th>Email</th><th>Telephone</th><th>Status</th><th>Joined</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['member_number'])?></td><td><?=e($r['student_id']?:'—')?></td><td><strong><?=e($r['full_name'])?></strong></td><td><?=e($r['email'])?></td><td><?=e($r['phone']?:'—')?></td><td><span class="badge-status <?=e($r['status'])?>"><?=e(ucfirst($r['status']))?></span></td><td><?=e($r['date_joined'])?></td><td><a class="btn btn-small btn-secondary" href="edit.php?id=<?=$r['member_id']?>">Edit</a> <form class="inline-form" method="post" action="delete.php" onsubmit="return confirm('Delete this member? Members with loan history cannot be deleted.');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['member_id']?>"><button class="btn btn-small btn-danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="empty-state">No members found.</td></tr><?php endif;?></tbody></table></div></section></main><?php require __DIR__.'/../includes/footer.php';?>